import { useState, useEffect } from 'react';
import InvoiceTable from './InvoiceTable';
import mockData from './mockData';

export default function App() {
  const [sortedData, setSortedData] = useState(mockData);
  const [sortConfig, setSortConfig] = useState<{ key: string | null; direction: 'ascending' | 'descending' | null }>({
    key: null,
    direction: null,
  });

  useEffect(() => {
    setSortedData(mockData);
  }, []);

  const handleSort = (key: string) => {
    let direction: 'ascending' | 'descending' = 'ascending';

    if (sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    } else if (sortConfig.key === key && sortConfig.direction === 'descending') {
      direction = 'ascending';
    }

    setSortConfig({ key, direction });
    const sorted = [...mockData].sort((a, b) => {
      if (a[key] < b[key]) return direction === 'ascending' ? -1 : 1;
      if (a[key] > b[key]) return direction === 'ascending' ?  1 : -1;
      return 0;
    });
    setSortedData(sorted);
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6 font-sans">
      <h1 className="text-2xl font-bold mb-6 text-gray-800">Invoices</h1>
      <InvoiceTable
        data={sortedData}
        onSort={handleSort}
        sortConfig={sortConfig}
      />
    </div>
  );
}
