### InvoiceTable.tsx
```tsx
import React from 'react';

interface Invoice {
  id: number;
  number: string;
  customer: string;
  amount: number;
  status: 'Paid' | 'Pending' | 'Overdue';
}

interface TableProps {
  data: Invoice[];
  onSort: (key: string) => void;
  sortConfig: { key: string | null; direction: 'ascending' | 'descending' | null };
}

const getStatusColor = (status: string): string => {
  switch (status) {
    case 'Paid':
      return 'bg-green-100 text-green-800';
    case 'Pending':
      return 'bg-yellow-100 text-yellow-800';
    case 'Overdue':
      return 'bg-red-100 text-red-800';
    default:
      return 'bg-gray-100 text-gray-800';
  }
};

const InvoiceTable: React.FC<TableProps> = ({ data, onSort, sortConfig }) => {
  const totalAmount = data.reduce((acc, item) => acc + item.amount, 0);

  const renderSortIcon = (key: string) => {
    if (sortConfig.key === key) {
      return sortConfig.direction === 'ascending' ? '↑' : '↓';
    }
    return '';
  };

  return (
    <div className="table-container">
      <table className="w-full">
        <thead>
          <tr>
            <th onClick={() => onSort('number')} className="cursor-pointer">
              Number {renderSortIcon('number')}
            </th>
            <th onClick={() => onSort('customer')} className="cursor-pointer">
              Customer {renderSortIcon('customer')}
            </th>
            <th onClick={() => onSort('amount')} className="cursor-pointer">
              Amount {renderSortIcon('amount')}
            </th>
            <th onClick={() => onSort('status')} className="cursor-pointer">
              Status {renderSortIcon('status')}
            </th>
          </tr>
        </thead>
        <tbody>
          {data.map((invoice) => (
            <tr key={invoice.id}>
              <td>{invoice.number}</td>
              <td>{invoice.customer}</td>
              <td>${invoice.amount.toFixed(2)}</td>
              <td>
                <span className={`status-badge ${getStatusColor(invoice.status)}`}>
                  {invoice.status}
                </span>
              </td>
            </tr>
          ))}
          <tr className="total-row">
            <td colSpan={3} className="text-right font-bold">
              Total
            </td>
            <td className="amount text-right font-bold text-accent">
              ${totalAmount.toFixed(2)}
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  );
};

export default InvoiceTable;
